<?php
require_once __DIR__.'/includes/functions.php';$page_title='Your bag';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['product_id']??0);if($action==='remove'){unset($_SESSION['cart'][$id]);flash('success','Item removed.');}elseif($action==='update'){foreach(($_POST['qty']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$pid]);else $_SESSION['cart'][$pid]=min(20,$qty);}flash('success','Bag updated.');}redirect('cart.php');}
$items=cart_items();include __DIR__.'/includes/header.php'; ?>
<div class="container py-5"><span class="eyebrow">Almost yours</span><h1 class="section-title mt-2 mb-4">Your bag (<?= cart_count() ?>)</h1><?php if(!$items): ?><div class="text-center py-5"><i class="bi bi-bag fs-1"></i><h3 class="mt-3">Your bag is taking a break.</h3><p class="muted">Find something that feels like you.</p><a class="btn btn-dark mt-2" href="<?= e(url('products.php')) ?>">Explore styles</a></div><?php else: ?><div class="row g-4"><div class="col-lg-8"><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="update"><?php foreach($items as $p): ?><div class="d-flex gap-3 border-bottom py-3"><img src="<?= e($p['image_url']) ?>" style="width:110px;height:135px;object-fit:cover" alt="<?= e($p['name']) ?>"><div class="flex-grow-1"><span class="product-category"><?= e($p['category']) ?></span><h5><?= e($p['name']) ?></h5><div class="price"><?= money($p['sale_price'] ?: $p['price']) ?></div><div class="d-flex align-items-center gap-2 mt-3"><label class="small" for="q<?= (int)$p['id'] ?>">Qty</label><input id="q<?= (int)$p['id'] ?>" class="form-control quantity-input" type="number" min="0" max="20" name="qty[<?= (int)$p['id'] ?>]" value="<?= (int)$p['quantity'] ?>"><span class="ms-auto fw-bold"><?= money($p['line_total']) ?></span></div></div></div><?php endforeach; ?><button class="btn btn-outline-dark mt-3">Update bag</button></form><?php foreach($items as $p): ?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= (int)$p['id'] ?>"><button class="btn btn-sm btn-link text-danger">Remove <?= e($p['name']) ?></button></form><?php endforeach; ?></div><div class="col-lg-4"><div class="summary-box"><h4>Order summary</h4><div class="d-flex justify-content-between my-3"><span>Subtotal</span><span><?= money(cart_subtotal()) ?></span></div><div class="d-flex justify-content-between mb-3"><span>Shipping</span><span><?= cart_subtotal()>=1499?'FREE':'₹99' ?></span></div><hr><div class="d-flex justify-content-between fw-bold fs-5"><span>Estimated total</span><span><?= money(cart_subtotal()+(cart_subtotal()>=1499?0:99)) ?></span></div><a class="btn btn-dark w-100 mt-4" href="<?= e(url('checkout.php')) ?>">Continue to checkout</a><p class="small muted mt-3 mb-0">Coupon codes can be applied at checkout.</p></div></div></div><?php endif; ?></div>
